import SwiftUI

/// A field that holds the key of another record, picked from a list the
/// field's source reads a page at a time: searched by the service as the
/// person types when the source names search, and otherwise among the
/// one page read.
public struct Lookup: View {
    let field: FieldSchema
    let label: String
    @Binding var value: String
    let texts: Texts
    var readOnly = false
    var onPick: ((Fields) -> Void)? = nil
    @State private var chosen: String = ""
    @State private var picking = false

    public var body: some View {
        LabeledContent(label) {
            Button(chosen.isEmpty ? (value.isEmpty ? say(texts, "screens.none") : value) : chosen) { picking = true }
                .disabled(readOnly)
        }
        .sheet(isPresented: $picking) {
            NavigationStack {
                LookupList(field: field, texts: texts) { record in
                    if let record {
                        value = record[field.value ?? ""]?.text ?? ""
                        chosen = (field.text ?? []).map { record[$0]?.text ?? "" }.joined(separator: " ")
                        onPick?(record)
                    } else {
                        value = ""
                        chosen = ""
                    }
                    picking = false
                }
                .navigationTitle(label)
            }
        }
    }
}

/// The records a lookup picks from, read from its source, with a search
/// box when the source searches or the page read is searched here.
struct LookupList: View {
    let field: FieldSchema
    let texts: Texts
    let pick: (Fields?) -> Void
    @State private var search = ""
    @State private var records: [Fields] = []
    @State private var failed = false

    var shown: [Fields] {
        guard field.source?.search == nil, !search.isEmpty else {
            return records
        }
        let needle = search.lowercased()
        return records.filter { record in
            (field.text ?? []).contains { record[$0]?.text.lowercased().contains(needle) ?? false }
        }
    }

    var body: some View {
        List {
            if failed {
                Text(say(texts, "screens.failed")).foregroundStyle(.red)
            } else if shown.isEmpty {
                Text(say(texts, "screens.nothingMatches")).foregroundStyle(.secondary)
            }
            Button(say(texts, "screens.none")) { pick(nil) }
            ForEach(Array(shown.enumerated()), id: \.offset) { _, record in
                Button((field.text ?? []).map { record[$0]?.text ?? "" }.joined(separator: " ")) { pick(record) }
            }
        }
        .searchable(text: $search, prompt: say(texts, "screens.search"))
        .task(id: field.source?.search == nil ? "" : search) { await read() }
    }

    @MainActor
    private func read() async {
        guard let source = field.source else {
            return
        }
        var query = [URLQueryItem(name: source.pageSize.name, value: String(source.pageSize.value))]
        if let searched = source.search, !search.isEmpty {
            query.append(URLQueryItem(name: searched, value: search))
        }
        do {
            let answer = try await Service.send("GET", source.path, query: query)
            guard answer.ok, let body = answer.body else {
                failed = true
                return
            }
            failed = false
            records = (body[source.items]?.items ?? []).map(\.members)
        } catch {
            failed = true
        }
    }
}
